using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
class FittedEllipse {
 public PointF Centre;public double RadiusX,RadiusY,Angle,Start,Direction;
 public PointF At(double angle){double x=RadiusX*Math.Cos(angle),y=RadiusY*Math.Sin(angle);return new PointF(Centre.X+(float)(x*Math.Cos(Angle)-y*Math.Sin(Angle)),Centre.Y+(float)(x*Math.Sin(Angle)+y*Math.Cos(Angle)));}
 public double Parameter(PointF p){double x=p.X-Centre.X,y=p.Y-Centre.Y;return Math.Atan2((-x*Math.Sin(Angle)+y*Math.Cos(Angle))/RadiusY,(x*Math.Cos(Angle)+y*Math.Sin(Angle))/RadiusX);}
 public static FittedEllipse Fit(List<PointF> raw){if(raw.Count<8)return null;double length=0;for(int i=1;i<raw.Count;i++)length+=StrokeSession.Distance(raw[i-1],raw[i]);if(length<20)return null;var pts=new List<PointF>();double step=length/160,travel=0,next=0;for(int i=1;i<raw.Count;i++){var a=raw[i-1];var b=raw[i];double d=StrokeSession.Distance(a,b);while(next<=travel+d&&d>0){double t=(next-travel)/d;pts.Add(new PointF(a.X+(float)((b.X-a.X)*t),a.Y+(float)((b.Y-a.Y)*t)));next+=step;}travel+=d;}if(pts.Count<8)return null;
  double mx=pts.Average(p=>(double)p.X),my=pts.Average(p=>(double)p.Y),scale=Math.Max(pts.Max(p=>p.X)-pts.Min(p=>p.X),pts.Max(p=>p.Y)-pts.Min(p=>p.Y))/2;if(scale<3)return null;
  double[,] matrix=new double[5,6];foreach(var p in pts){double x=(p.X-mx)/scale,y=(p.Y-my)/scale;double[] row={x*x,x*y,y*y,x,y};for(int i=0;i<5;i++){for(int j=0;j<5;j++)matrix[i,j]+=row[i]*row[j];matrix[i,5]+=row[i];}}
  for(int i=0;i<5;i++){int best=i;for(int j=i+1;j<5;j++)if(Math.Abs(matrix[j,i])>Math.Abs(matrix[best,i]))best=j;if(Math.Abs(matrix[best,i])<1e-9)return null;for(int j=i;j<=5;j++){double swap=matrix[i,j];matrix[i,j]=matrix[best,j];matrix[best,j]=swap;}double pivot=matrix[i,i];for(int j=i;j<=5;j++)matrix[i,j]/=pivot;for(int k=0;k<5;k++)if(k!=i){double f=matrix[k,i];for(int j=i;j<=5;j++)matrix[k,j]-=f*matrix[i,j];}}
  double a0=matrix[0,5],b0=matrix[1,5]/2,c0=matrix[2,5],d0=matrix[3,5],e0=matrix[4,5],det=a0*c0-b0*b0;if(det<=1e-9)return null;double cx=(b0*e0-c0*d0)/(2*det),cy=(b0*d0-a0*e0)/(2*det),rhs=1+a0*cx*cx+2*b0*cx*cy+c0*cy*cy,delta=Math.Sqrt((a0-c0)*(a0-c0)+4*b0*b0),l1=(a0+c0+delta)/2,l2=(a0+c0-delta)/2;if(l1<=0||l2<=0||rhs<=0)return null;
  var result=new FittedEllipse{Centre=new PointF((float)(mx+cx*scale),(float)(my+cy*scale)),RadiusX=Math.Sqrt(rhs/l1)*scale,RadiusY=Math.Sqrt(rhs/l2)*scale,Angle=.5*Math.Atan2(2*b0,a0-c0)};if(result.RadiusX<2||result.RadiusY/result.RadiusX>30||result.RadiusY>scale*3)return null;
  double error=0,turn=0,previous=result.Parameter(pts[0]);foreach(var p in pts){double t=result.Parameter(p);double dx=p.X-result.Centre.X,dy=p.Y-result.Centre.Y,u=(dx*Math.Cos(result.Angle)+dy*Math.Sin(result.Angle))/result.RadiusX,v=(-dx*Math.Sin(result.Angle)+dy*Math.Cos(result.Angle))/result.RadiusY;error+=Math.Pow(Math.Sqrt(u*u+v*v)-1,2);double dt=t-previous;while(dt>Math.PI)dt-=2*Math.PI;while(dt< -Math.PI)dt+=2*Math.PI;turn+=dt;previous=t;}if(Math.Sqrt(error/pts.Count)>.22||Math.Abs(turn)<2.5||Math.Abs(turn)>8)return null;result.Start=result.Parameter(raw[0]);result.Direction=Math.Sign(turn);return result;
 }
}
partial class StrokeSession {
 bool fittedClosed;
 public bool FitClosedEllipse(){var fit=FittedEllipse.Fit(points);if(fit==null)return false;int count=Math.Max(96,Math.Min(20000,(int)Math.Ceiling(Math.PI*2*Math.Max(fit.RadiusX,fit.RadiusY)/Math.Max(.5f,size*.1f))));var pressureSamples=pressures.ToArray();float initial=hardware?PressureScale(pressureSamples[0]):1;brush.Reset(fit.At(fit.Start),size*initial);for(int i=1;i<=count;i++){float t=(float)i/count,scale=1;if(hardware){float index=t*(pressureSamples.Length-1);int lo=Math.Min(pressureSamples.Length-1,(int)index),hi=Math.Min(pressureSamples.Length-1,lo+1);float sample=pressureSamples[lo]+(pressureSamples[hi]-pressureSamples[lo])*(index-lo);if(t>.9f)sample=sample+(pressureSamples[0]-sample)*(t-.9f)/.1f;scale=PressureScale(sample);}brush.MoveSized(fit.At(fit.Start+fit.Direction*Math.PI*2*t),size*scale);}fittedClosed=true;return true;}
}
partial class Canvas {
 bool ellipseStroke;
 public void TestEllipseGesture(List<PointF> points){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,(int)points[0].X,(int)points[0].Y,0));ellipseStroke=true;for(int i=1;i<points.Count-1;i++)OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,(int)points[i].X,(int)points[i].Y,0));var end=points.Last();OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,(int)end.X,(int)end.Y,0));}
}
partial class Studio {
 static List<PointF> EllipseSamples(float rx,float ry,double angle,bool noisy){var pts=new List<PointF>();for(int i=0;i<=180;i++){double t=i*Math.PI*2/180,x=rx*Math.Cos(t),y=ry*Math.Sin(t),jitter=noisy?Math.Sin(i*2.3)*2:0;pts.Add(new PointF(300+(float)(x*Math.Cos(angle)-y*Math.Sin(angle)+jitter),250+(float)(x*Math.Sin(angle)+y*Math.Cos(angle)+jitter*.6)));}return pts;}
 public void TestVersion22(){foreach(double angle in new[]{0.0,.6,1.4})foreach(float ry in new[]{45f,100f}){var pts=EllipseSamples(100,ry,angle,true);var fit=FittedEllipse.Fit(pts);if(fit==null||StrokeSession.Distance(fit.Centre,new PointF(300,250))>2||Math.Abs(fit.RadiusY-100)>3||Math.Abs(fit.RadiusX-ry)>3)throw new Exception("Ellipse fit accuracy");pts.Reverse();if(FittedEllipse.Fit(pts)==null)throw new Exception("Clockwise fit");}var arc=EllipseSamples(100,60,.6,false).Take(35).ToList();if(FittedEllipse.Fit(arc)!=null||FittedEllipse.Fit(new List<PointF>{new PointF(0,0),new PointF(100,100)})!=null)throw new Exception("Reject incomplete ellipse");
  SetDocument(new Document("A4",100),null);SelectTool("Pen");canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.PressureMode="No pressure";canvas.Smoothing=80;canvas.Predictive=true;canvas.BrushSize=8;canvas.Ink=Color.Blue;var loop=EllipseSamples(100,60,.6,true);byte[] before=Document.Png(canvas.Doc.Selected.Image);int history=undo.Count;canvas.TestEllipseGesture(loop);if(undo.Count!=history+1)throw new Exception("Ellipse single undo");var fit2=FittedEllipse.Fit(loop);for(int i=0;i<36;i++){var p=fit2.At(i*Math.PI*2/36);if(canvas.Doc.Selected.Image.GetPixel((int)p.X,(int)p.Y).A==0)throw new Exception("Ellipse continuous outline");}Travel(undo,redo);if(!Document.Png(canvas.Doc.Selected.Image).SequenceEqual(before))throw new Exception("Ellipse undo");Travel(redo,undo);
  canvas.SetSelectionMode("Box selection");canvas.TestDrag(new Point(0,0),new Point(300,500));using(var g=Graphics.FromImage(canvas.Doc.Selected.Image))g.Clear(Color.Red);SelectTool("Eraser");canvas.BrushSize=16;canvas.PressureMode="No pressure";canvas.TestEllipseGesture(loop);PointF left=fit2.At(Math.PI),right=fit2.At(0);if(left.X>right.X){var swap=left;left=right;right=swap;}if(canvas.Doc.Selected.Image.GetPixel((int)left.X,(int)left.Y).A!=0||canvas.Doc.Selected.Image.GetPixel((int)right.X,(int)right.Y).A!=255)throw new Exception("Ellipse eraser selection clip");canvas.ClearSelection();dirty=false;
 }
}
